package com.kartyavya.report.config; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.Configuration; import org.springframework.web.servlet.config.annotation.*; import java.nio.file.Paths; @Configuration public class WebConfig implements WebMvcConfigurer{@Value("${storage.root:./uploads}")String root;public void addResourceHandlers(ResourceHandlerRegistry r){r.addResourceHandler("/uploads/**").addResourceLocations(Paths.get(root).toAbsolutePath().normalize().toUri().toString());}}
